151: function MenuUtil.CreateContextMenu(ownerRegion, generator, ...)
152: 	if not ownerRegion then
153: 		ownerRegion = GetAppropriateTopLevelParent();
154: 	end
155: 
156: 	local menuMixin = securecallfunction(SecureGetMenuMixin, ownerRegion);
157: 	local elementDescription = MenuUtil.CreateRootMenuDescription(menuMixin);
158: 
159: 	Menu.PopulateDescription(generator, ownerRegion, elementDescription, ...);
160: 
161: 	local menu = Menu.GetManager():OpenContextMenu(ownerRegion, elementDescription);
162: 	if menu then
163: 		PlaySound(SOUNDKIT.IG_MAINMENU_OPTION_CHECKBOX_ON);
164: 	end
165: 
166: 	return menu;
167: end
